    if (!targetId) return
    setLoading(true)
    setError(null)
    setResult(null)
    try {
      const res = await axios.get(`${API}/reviewer/${targetId}`)
      setResult(res.data)
    } catch (err) {
      setError(err.response?.status === 404 ? "Reviewer not found in dataset" : "API error — make sure FastAPI is running")
    } finally {
      setLoading(false)
    }
  }

function Screen3() {
  const [rings, setRings]     = useState([])
  const [loading, setLoading] = useState(true)
  const [error, setError]     = useState(null)

  useEffect(() => {
    axios.get(`${API}/graph/rings`)
      .then(res => setRings(res.data.rings))
      .catch(() => setError("API error — make sure FastAPI is running"))
      .finally(() => setLoading(false))
  }, [])

  const risk = (score) => {
    if (score > 0.10) return { label: "High",   tier: "high" }
    if (score > 0.05) return { label: "Medium", tier: "med" }
    return               { label: "Low",    tier: "low" }
  }

  return (
    <div className="max-w-5xl mx-auto py-12 px-4">
      <p className="text-[11px] tracking-[.18em] uppercase text-[#33d9c4] font-mono mb-2">Screen 03</p>
      <h1 className="font-display text-2xl font-semibold mb-2">Fraud Ring Network</h1>
      <p className="text-[#93a3b5] mb-6 text-sm max-w-2xl">
        Reviewers connected by shared product reviews. Small, tight-knit clusters with high fraud rates are the ones worth investigating.
      </p>

      <div className="panel panel-pad mb-6">
        <h2 className="font-display font-semibold text-sm mb-3">Interactive Graph — drag nodes to explore</h2>
        <iframe
          src="/fraud_rings.html"
          width="100%"
          height="500px"
          className="rounded-xl border border-[#232f3d]"
          title="Fraud Ring Graph"
        />
      </div>

      <div className="panel panel-pad">
        <h2 className="font-display font-semibold text-sm mb-4">Fraud Ring Statistics</h2>

        {loading && <p className="text-[#5f7186] text-sm">Loading…</p>}
        {error   && <p className="text-[#ff9a97] text-sm">{error}</p>}

        {!loading && !error && (
          <table className="w-full text-sm">
            <thead>
              <tr className="text-left">
                <th className="pb-2 font-mono">Community</th>
                <th className="pb-2">Size</th>
                <th className="pb-2">Fraud Rate</th>
                <th className="pb-2">Total Reviews</th>
                <th className="pb-2">Products</th>
                <th className="pb-2">Risk</th>
              </tr>
            </thead>
            <tbody>
              {rings.map(ring => {
                const r = risk(ring.avg_fraud_score)
                return (
                  <tr key={ring.community_id}>
                    <td className="py-2.5 font-mono text-[#93a3b5]">{ring.community_id}</td>
                    <td className="py-2.5">{ring.size}</td>
                    <td className="py-2.5 font-mono">{(ring.avg_fraud_score * 100).toFixed(1)}%</td>
                    <td className="py-2.5 font-mono">{ring.total_reviews.toLocaleString()}</td>
                    <td className="py-2.5">{ring.products_targeted}</td>
                    <td className="py-2.5">
                      <span className={`chip chip-${r.tier}`}>{r.label}</span>
                    </td>
                  </tr>
                )
              })}
            </tbody>
          </table>
        )}
      </div>
    </div>
  )
}

(score) => {
    if (score > 0.10) return { label: "High",   tier: "high" }
    if (score > 0.05) return { label: "Medium", tier: "med" }
    return               { label: "Low",    tier: "low" }
  }

function Screen4() {
  const [threshold,          setThreshold]          = useState(0.40)
  const [dailyVolume,        setDailyVolume]        = useState(1000)
  const [investigationCost,  setInvestigationCost]  = useState(50)
  const [fraudRate,          setFraudRate]          = useState(5)
  const [result,             setResult]             = useState(null)
  const [prCurve,            setPrCurve]            = useState([])
  const [curveError,         setCurveError]         = useState(null)
  const [curveLoading,       setCurveLoading]       = useState(true)
  
  useEffect(() => {
    setCurveLoading(true)
    setCurveError(null)
    axios.get(`${API}/graph/pr-curve`)
      .then(res => {
        const points = res.data?.points ?? []
        if (points.length === 0) {
          setCurveError("PR curve endpoint returned no points — check pr_curve.json is present on the API.")
          return
        }
        const sorted = [...points]
          .map(p => ({ threshold: p.threshold, recall: p.recall, precision: p.precision }))
          .sort((a, b) => a.recall - b.recall)
        setPrCurve(sorted)
      })
      .catch(err => {
        setCurveError(
          err.response
            ? `API error ${err.response.status} on /graph/pr-curve`
            : "Could not reach /graph/pr-curve — is the API running and reachable?"
        )
      })
      .finally(() => setCurveLoading(false))
  }, [])

  useEffect(() => {
    axios.get(`${API}/graph/cost-analysis`, {
      params: {
        threshold,
        daily_volume     : dailyVolume,
        fraud_rate       : fraudRate / 100,
        investigation_cost: investigationCost
      }
    }).then(res => setResult(res.data))
      .catch(() => {})
  }, [threshold, dailyVolume, investigationCost, fraudRate])

  return (
    <div className="max-w-4xl mx-auto py-12 px-4">
      <p className="text-[11px] tracking-[.18em] uppercase text-[#33d9c4] font-mono mb-2">Screen 04</p>
      <h1 className="font-display text-2xl font-semibold mb-2">Investigation Cost Calculator</h1>
      <p className="text-[#93a3b5] mb-2 text-sm">Adjust the threshold and business parameters to estimate real-world investigation costs.</p>
      <p className="text-[#5f7186] mb-6 text-xs italic">
        Precision/recall here are computed on a sample preserving the real-world fraud rate — this shows expected production performance, not the balanced-evaluation metrics reported on the Model Metrics screen.
      </p>

      <div className="grid grid-cols-2 gap-4 mb-6">
        {[
          { label: `Detection Threshold`, sub: threshold,          value: threshold,         set: setThreshold,         min: 0.10, max: 0.90, step: 0.05 },
          { label: `Daily Review Volume`, sub: dailyVolume,        value: dailyVolume,       set: setDailyVolume,       min: 100,  max: 10000, step: 100 },
          { label: `Investigation Cost`,  sub: `₹${investigationCost}`, value: investigationCost, set: setInvestigationCost, min: 10,   max: 500,   step: 10 },
          { label: `Estimated Fraud Rate`,sub: `${fraudRate}%`,    value: fraudRate,         set: setFraudRate,         min: 1,    max: 20,    step: 1 },
        ].map(s => (
          <div key={s.label} className="panel panel-tight">
            <div className="flex justify-between items-baseline mb-2">
              <label className="text-xs font-medium text-[#93a3b5]">{s.label}</label>
              <span className="font-mono text-sm text-[#33d9c4]">{s.sub}</span>
            </div>
            <input
              type="range" min={s.min} max={s.max} step={s.step}
              value={s.value}
              onChange={e => s.set(parseFloat(e.target.value))}
              className="w-full accent-[#33d9c4]"
            />
          </div>
        ))}
      </div>

      {result && (
        <div className="grid grid-cols-2 md:grid-cols-4 gap-3 mb-6">
          {[
            { label: "Precision",            value: result.precision },
            { label: "Recall",               value: result.recall },
            { label: "Daily Investigations", value: result.flagged_per_day },
            { label: "Monthly Cost",         value: `₹${result.cost_per_month.toLocaleString()}` },
          ].map(m => (
            <div key={m.label} className="stat-card">
              <div className="stat-value">{m.value}</div>
              <div className="stat-label">{m.label}</div>
            </div>
          ))}
        </div>
      )}

      <div className="grid grid-cols-2 gap-4 mb-6">
        <div className="panel panel-pad">
          <div className="flex items-baseline justify-between mb-3">
            <h3 className="font-display font-semibold text-sm">Precision–Recall Curve</h3>
            <span className="text-[11px] text-[#5f7186] font-mono">● marker = current threshold</span>
          </div>

          {curveLoading && (
            <p className="text-[#5f7186] text-sm py-16 text-center">Loading curve…</p>
          )}

          {!curveLoading && curveError && (
            <div className="p-3 rounded-xl border border-[#ef6f6c]/30 bg-[#ef6f6c]/10 text-[#ff9a97] text-sm">
              {curveError}
            </div>
          )}

          {!curveLoading && !curveError && prCurve.length > 0 && (
            <ResponsiveContainer width="100%" height={250}>
              <LineChart data={prCurve}>
                <XAxis
                  type="number"
                  dataKey="recall"
                  stroke="#5f7186"
                  domain={[0, 1]}
                  label={{ value: "Recall", position: "insideBottom", offset: -2, fill: "#5f7186" }}
                  tick={{ fontSize: 11, fill: "#5f7186" }}
